class DepartmentWikiAPIViewSet(PagesAPIViewSet):
    def get_queryset(self):
        dept_id = self.request.query_params.get('department_id')
        if not self.request.user.is_authenticated:
            return DepartmentWikiPage.objects.none()
        if dept_id:
            if str(self.request.user.department_id) != str(dept_id):
                raise PermissionDenied("You do not belong to this department.")
            return DepartmentWikiPage.objects.filter(department_id=dept_id).live().public()
        return DepartmentWikiPage.objects.none()
